"""FM-16J original editorial pathways. Difficulty and rubrics remain teacher pending."""
import sympy as s
from calibration_bank import LEVELS,L
M=s.Matrix
k,h,t=s.symbols('k h t',real=True)
PATHS={'zero-matrix':'MAT.identity.zero','scalar-matrix':'MAT.scalar.scale','vector-plane':'VEC.plane.vector','zero-cross':'VEC.vector-properties.zero'}
RATIONALES={
'zero-matrix':['Recall additive zero.','Distinguish zero addition and multiplication.','Compute a matrix cancellation.','Connect a matrix product with its action on nonzero columns.','Recover a singular parameter from a prescribed null vector and characterise the nullspace.','Classify all annihilating matrices, including singular and nonsingular cases.'],
'scalar-matrix':['Scale signed numbers.','Diagnose incomplete entrywise scaling.','Calculate an entrywise scalar product.','Combine scaling and addition to recover two scalar coefficients.','Infer a scalar from an unsigned determinant constraint and check both signs.','Classify scalar proportionality across two parameters, including zero matrices.'],
'vector-plane':['Recall displacement vectors.','Diagnose dependence of two plane directions.','Construct a vector plane from three noncollinear points.','Connect vector and Cartesian plane representations and check membership.','Recover an unknown coordinate from plane membership, proving uniqueness.','Classify the existence and number of planes containing a line and two parameter-dependent points.'],
'zero-cross':['Recall proportionality.','Distinguish zero cross product from parallel nonzero directions.','Test parallelism by calculating a cross product.','Use displacement cross products to test collinearity.','Combine parallelism and magnitude to recover all vectors.','Classify cross-product zeros in parameter space, distinguishing zero vectors and parallel nonzero vectors.']}

def make(path,l,v):
 if path not in PATHS or l not in LEVELS or v not in (1,2,3):raise ValueError('Unknown cell')
 a=v+1;b=v+3;c=2*v+3
 if path=='zero-matrix':
  A=M([[a,-1],[b,c]]);Z=s.zeros(2)
  if l==1:
   q=f'Find the number x such that {a}+x={a}.';f=[0];ans='x=0.';steps=[f'Subtract {a} from both sides. The additive identity is 0.'];hints=['Undo addition.','Which number leaves a sum unchanged?'];mistake='Using the multiplicative identity 1.'
  elif l==2:
   q=f'Let A={L(A)} and O be the 2 by 2 zero matrix. A learner says A+O and AO both equal A. Explain which claim is false and give the two results.';f=[A,Z];ans=f'A+O={L(A)}; AO={L(Z)}.';steps=['Adding zero leaves each entry unchanged.','Every entry in the product with the zero matrix is a sum of zero terms. Therefore AO is the zero matrix, not A.'];hints=['Separate addition from multiplication.','Consider one entry of the product.'];mistake='Treating zero as the multiplicative identity.'
  elif l==3:
   B=M([[1,b],[0,a]]);C=A+B;f=[C];q=f'Find X satisfying X-A-B=O, where A={L(A)}, B={L(B)}, and O is the 2 by 2 zero matrix.';ans=L(C);steps=['Add A and B to both sides.',f'Add corresponding entries: X={ans}.'];hints=['Rearrange before computing.','The zero matrix is the additive identity.'];mistake='Subtracting B instead of adding it.'
  elif l==4:
   A=M([[a,1],[a*b,b]]);D=M([[1,2],[-a,-2*a]]);f=[A*D,A.det()];q=f'Let A={L(A)}, B={L(D)}. Calculate AB and det(A). Explain why a zero product here does not imply that either factor is the zero matrix.';ans=f'AB={L(Z)}; det(A)=0; both factors nonzero.';steps=[f'Each column of B is proportional to {L(M([1,-a]))}, which A maps to zero.',f'Consequently AB={L(Z)}. The rows of A are proportional, so det(A)=0.', 'Both A and B have nonzero entries; A is singular, so cancellation using an inverse is impossible.'];hints=['Multiply by each column.','Check the determinant before attempting cancellation.'];mistake='Cancelling a singular matrix.'
  elif l==5:
   A=M([[a,1],[k,b]]);w=M([c,-a*c]);f=[a*b,M([1,-a])];q=f'The nonzero vector {L(w)} is mapped to zero by A={L(A)}. Find k and then describe every vector mapped to zero by A. Prove that your parameter value is unique.';ans=f'k={a*b}; all vectors t{L(f[1])}, t real.';steps=[f'The first row gives zero; the second gives {L((A*w)[1])}=0.',f'As {c} is nonzero, k={a*b} uniquely.',f'At that value the second row is {b} times the first. The sole independent equation is {a}x+y=0, giving the stated family.'];hints=['Use the given nonzero vector in both rows.','Solve the remaining homogeneous equation for a general vector.'];mistake='Concluding that only the supplied vector maps to zero.'
  else:
   A=M([[a,1],[k,b]]);basis=M([1,-a]);f=[A.det(),a*b,basis];q=f'For each real k, classify every real 2 by 2 matrix B satisfying AB=O, where A={L(A)} and O is the zero matrix. State when nonzero B exists and prove your description is exhaustive.';ans=f'If k differs from {a*b}, only B=O. If k={a*b}, every B has form $\\begin{{pmatrix}}p&q\\\\-{a}p&-{a}q\\end{{pmatrix}}$ with p,q real; it is nonzero iff (p,q) differs from (0,0).';steps=[f'det(A)={L(A.det())}. If nonzero, left-multiply AB=O by the inverse to obtain B=O.',f'If k={a*b}, the second row is {b} times the first. Each column (x,y) of B must satisfy {a}x+y=0.',f'Each column is independently a multiple of {L(basis)}, so the displayed two-parameter family contains every solution.', 'Conversely both rows annihilate each such column. Nonzero B exists precisely in the singular case.'];hints=['Treat B as two unknown columns.','Separate the invertible and singular cases.'];mistake='Assuming a zero matrix product forces a zero factor.'
 elif path=='scalar-matrix':
  A=M([[a,-1],[b,c]])
  if l==1:
   f=[-a*b,a*c];q=f'Multiply each of the signed numbers {-b} and {c} by {a}.';ans=f'{-a*b}, {a*c}.';steps=['Apply the scalar separately to both numbers.',f'The products are {ans}'];hints=['Check the sign.','Apply the multiplier to each number.'];mistake='Scaling only one number.'
  elif l==2:
   wrong=M([[2*a,-1],[b,2*c]]);f=[2*A];q=f'A learner writes 2A={L(wrong)} for A={L(A)}. Diagnose the error and correct it.';ans=L(2*A);steps=['Scalar multiplication scales every entry, not just the diagonal.',f'The corrected matrix is {ans}.'];hints=['Check the off-diagonal entries.','The scalar multiplies each entry.'];mistake='Scaling only diagonal entries.'
  elif l==3:
   f=[-b*A];q=f'Calculate {-b}A for A={L(A)}.';ans=L(f[0]);steps=[f'Multiply all four entries by {-b}, preserving their positions.',f'The result is {ans}.'];hints=['Work entry by entry.','Check the signs of the off-diagonal entries.'];mistake='Changing the signs inconsistently.'
  elif l==4:
   B=M([[1,0],[0,1]]);D=a*A-b*B;f=[a,-b];q=f'Let A={L(A)}, I be the identity, and C={L(D)}. Recover both real scalars p,q such that pA+qI=C and verify the complete matrix equation.';ans=f'p={a}, q={-b}.';steps=[f'The upper-right entry of pA+qI is -p, so p={a}.',f'The upper-left entry is {a}p+q, hence q={-b}.',f'Substituting gives {L(D)} in all four entries, so both scalars are uniquely determined.'];hints=['Use an off-diagonal entry first.','Check the remaining entries after solving.'];mistake='Assuming one scalar controls both matrices.'
  elif l==5:
   A=M([[a,1],[0,b]]);target=a*b*c*c;f=[-c,c];q=f'A transformation has matrix A={L(A)}. A second transformation has matrix kA and multiplies areas by {target}. Determine every real k and state whether each transformation preserves or reverses orientation.';ans=f'k=+/-{c}; both preserve orientation.';steps=[f'The determinant of A is {a*b}. Scaling both rows gives det(kA)={a*b} times k squared.',f'The absolute determinant equals {target}, so k squared={c*c}.',f'Both k=-{c} and k={c} have positive determinant {target}; both preserve orientation. No other roots exist.'];hints=['The determinant of a 2 by 2 matrix scales by the square of the scalar.','Use unsigned area and signed determinant separately.'];mistake='Assuming negative scalar means negative determinant.'
  else:
   A=M([[k,a*k],[0,k]]);B=M([[h,a*h],[0,h*(h-b)]]);f=[h*(h-b-1),b+1];q=f'For each real pair (k,h), determine all real scalars r, if any, for which rA=B, where A={L(A)}, B={L(B)}. Include zero matrices and prove completeness.';ans=f'k=0,h=0: every r. k=0,h nonzero: none. k nonzero,h=0: r=0. k nonzero,h={b+1}: r=h/k. All other pairs: none.';steps=['If k=0, A=O. Equality is possible exactly when B=O, i.e. h=0, and then every r works.', 'If k is nonzero, the upper-left entry forces r=h/k.',f'The lower-right entry then requires h=h(h-{b}), equivalent to {L(f[0])}=0.',f'Hence h=0 or h={b+1}. For these values the off-diagonal entries also match, and the forced scalar works uniquely. The cases exhaust all real k,h.'];hints=['Separate k=0 before dividing.','Use two diagonal entries to find compatibility.'];mistake='Dividing by k without considering the zero matrix.'
 elif path=='vector-plane':
  P=M([1,2,3]);U=M([a,0,1]);V=M([0,b,0]);Q=P+U;R=P+V
  if l==1:
   f=[Q-P];q=f'Find displacement from P={L(P)} to Q={L(Q)}.';ans=L(f[0]);steps=[f'Subtract the coordinates of P from Q: {ans}.'];hints=['Use endpoint minus start.','Calculate all three components.'];mistake='Adding the position vectors.'
  elif l==2:
   f=[U.cross(2*U)];q=f'A learner describes a plane as r={L(P)}+s{L(U)}+t{L(2*U)} with real s,t. Explain why this describes a line instead of a plane.';ans='The directions are dependent; the cross product is zero and the set is a line.';steps=['Both directions are nonzero but one is twice the other.',f'The expression reduces to r={L(P)}+(s+2t){L(U)}. The single effective parameter describes a line.'];hints=['Compare the two directions.','Combine the parameters.'];mistake='Counting parameters without checking independence.'
  elif l==3:
   f=[P,U,V];q=f'Find a vector equation of the plane through P={L(P)}, Q={L(Q)}, R={L(R)}. Verify that the directions are independent.';ans=f'r={L(P)}+s{L(U)}+t{L(V)}, s,t real.';steps=[f'The displacements Q-P and R-P are {L(U)} and {L(V)}.',f'Their cross product is {L(U.cross(V))}, which is nonzero.',f'Therefore the vectors span a plane and the vector equation is {ans}'];hints=['Choose one point as the common origin of both displacements.','Test independence before forming the plane.'];mistake='Using position vectors as plane directions.'
  elif l==4:
   N=U.cross(V)/b;D=N.dot(P);W=P+2*U-V;f=[N,D,2,-1];q=f'Given r={L(P)}+s{L(U)}+t{L(V)}, obtain a Cartesian equation with integer normal whose first component is -1. Find the parameters of W={L(W)} and verify membership using the Cartesian equation.';ans=f'Normal {L(N)}, equation {L(N[0]*s.Symbol("x")+N[1]*s.Symbol("y")+N[2]*s.Symbol("z"))}={L(D)}; s=2,t=-1.';steps=[f'Cross the directions and divide by {b} to get normal {L(N)}.',f'The Cartesian equation has right-hand side n dot P={L(D)}.',f'W-P={L(W-P)}=2u-v, so s=2,t=-1.',f'Its scalar product with n is {L(N.dot(W))}, equal to the required constant.'];hints=['A normal is perpendicular to both directions.','Use two independent coordinate equations for the parameters.'];mistake='Omitting the plane constant.'
  elif l==5:
   W=M([1+a*c,2-b,k]);root=3+c;f=[root,c,-1];q=f'The point W={L(W)} lies on r={L(P)}+s{L(U)}+t{L(V)}. Determine k and both parameters, and justify uniqueness.';ans=f'k={root}, s={c}, t=-1.';steps=[f'The x-coordinate gives 1+{a}s={1+a*c}, so s={c}.',f'The y-coordinate gives 2+{b}t={2-b}, so t=-1.',f'The z-coordinate then fixes k=3+s={root}. Both independent coordinate equations have nonzero coefficients, so no other parameters or k work.'];hints=['Use coordinates not involving k first.','The same pair of parameters must fit every coordinate.'];mistake='Choosing separate parameters for each equation.'
  else:
   E=M([a,0,0]);U=M([0,k,h]);V=M([0,b*b*h,k]);det=k*k-b*b*h*h;f=[det,M([0,b,1]),M([0,-b,1])];q=f'For every real pair (k,h), classify the number of distinct planes containing the line r=t{L(E)} and both points P={L(U)}, Q={L(V)}. Give vector equations when possible and prove completeness.';ans=f'If k=h=0, infinitely many planes r=s{L(E)}+t(0,u,w), (u,w) not both zero, with proportional directions identified. If k={b}h and h is nonzero, unique plane r=s{L(E)}+t{L(f[1])}. If k=-{b}h and h is nonzero, unique plane r=s{L(E)}+t{L(f[2])}. Otherwise no plane.';steps=['Every plane containing the given line passes through the origin and contains its nonzero direction.',f'In the yz-plane the two point vectors have determinant {L(det)}. If it is nonzero, the two point vectors span the yz-plane; with the x direction they span 3D space, so no plane contains them all.', 'If k=h=0, both points are the origin and any plane through the x-axis works; a second direction can be chosen in the yz-plane, nonzero and up to proportionality.', f'Otherwise determinant zero gives k={b}h or k=-{b}h, with h nonzero. In either case the point vectors span one nonzero direction, respectively {L(f[1])} or {L(f[2])}. Together with the x direction this fixes the unique stated plane.', 'The determinant and zero cases exhaust all real parameters.'];hints=['Consider the span of the line direction and both position vectors.','Look at the determinant of the two yz-coordinate pairs.'];mistake='Assuming any line and any two points lie in one plane.'
 elif path=='zero-cross':
  U=M([a,b,1]);V=M([2*a,2*b,2])
  if l==1:
   f=[c];q=f'Find the multiplier taking vector (1,{a}) to ({c},{a*c}).';ans=f'{c}.';steps=[f'The first coordinate fixes the multiplier at {c}; the second agrees.'];hints=['Compare first coordinates.','Check both coordinates.'];mistake='Using different multipliers for different coordinates.'
  elif l==2:
   f=[U.cross(s.zeros(3,1))];q=f'Let u={L(U)} and v=(0,0,0). A learner says u cross v=0 proves the vectors define parallel lines. Explain the flaw.';ans='The cross product is zero, but v is not a valid direction vector.';steps=['Every term in the cross product with the zero vector is zero.','A line direction must be nonzero. Therefore the zero vector does not define a parallel line.'];hints=['Check whether both vectors can be line directions.','The cross product condition alone permits zero vectors.'];mistake='Treating the zero vector as a valid direction.'
  elif l==3:
   V=M([-c*a,-c*b,-c]);f=[U.cross(V),-c];q=f'Calculate the cross product of {L(U)} and {L(V)} and decide whether the two nonzero vectors are parallel. State their scalar multiplier.';ans=f'Zero cross product; parallel, multiplier {-c}.';steps=[f'The cross product is {L(U.cross(V))}.',f'Both vectors are nonzero, and v={-c}u, so they are parallel with opposite senses.'];hints=['Use the cross product formula.','Compare the corresponding components.'];mistake='Assuming parallel vectors must have the same sense.'
  elif l==4:
   P=M([1,2,3]);Q=P+U;R=P-c*U;S=P+M([a,b,2]);f=[(Q-P).cross(R-P),(Q-P).cross(S-P)];q=f'Given P={L(P)}, Q={L(Q)}, R={L(R)}, S={L(S)}, use cross products to decide which of R and S lie on the line PQ. Explain why.';ans='R lies on PQ; S does not.';steps=[f'PQ={L(Q-P)}, PR={L(R-P)}, PS={L(S-P)}.',f'PQ cross PR={L(f[0])}; PQ cross PS={L(f[1])}.', 'PQ is nonzero, so a displacement is along its line exactly when the cross product vanishes. Only R qualifies.'];hints=['Calculate displacements from P, not position vectors.','Test each cross product.'];mistake='Crossing absolute position vectors.'
  elif l==5:
   D=M([k,h,c]);# parallel to (a,b,1); fixed last component gives only one sign, use magnitude and first component variable
   D=M([k,h,t]);target=c*U.norm();f=[-c*U,c*U];q=f'Find every vector w parallel to u={L(U)} with magnitude {L(target)}. Use the zero cross-product condition and justify both solutions.';ans=f'w={L(f[0])} or {L(f[1])}.';steps=['Because u is nonzero, a zero cross product implies w=r u for real r.',f'Its magnitude is |r| times {L(U.norm())}, so |r|={c}.',f'Both r=-{c} and r={c} give the required positive magnitude and zero cross product. These exhaust the possible scalar multipliers.'];hints=['Express w as a multiple of u.','A magnitude constrains the absolute value of the multiplier.'];mistake='Discarding the opposite direction.'
  else:
   U=M([k,a,0]);V=M([h,k,0]);f=[k*k-a*h,k*k/a];q=f'For all real k,h, classify when u={L(U)} and v={L(V)} have zero cross product. In those cases distinguish a zero vector from two nonzero parallel vectors, give their scalar multiplier when defined, and prove completeness.';ans=f'Zero cross product iff h={L(f[1])}. At k=h=0, v is zero and cannot define a line. Otherwise both vectors are nonzero and v=(k/{a})u.';steps=[f'The cross product has third component {L(f[0])} and other components zero.',f'It vanishes exactly for h={L(f[1])}. The second component of u is {a}, so u is never zero.', 'The vector v is zero precisely when k=h=0, which lies on the zero-cross-product locus.',f'Otherwise k is nonzero on this locus and v=(k/{a})u by direct substitution; the scalar is unique from the second component. Off the locus the cross product is nonzero, so no cases are omitted.'];hints=['Compute the third component.','Check when either direction vanishes before calling the vectors parallel.'];mistake='Calling the zero vector a parallel line direction.'
 else:raise ValueError(path)
 def enc(e):
  if type(e) is bool:return e
  if isinstance(e,s.MatrixBase):return {'matrix':[[str(x) for x in row] for row in e.tolist()]}
  return str(e)
 return dict(path=path,focus_skill=PATHS[path],tier=l,variant=v,assessment_role='prerequisite_bridge' if l==1 else 'concept_diagnostic' if l==2 else 'direct_focus_task',question_latex=q,final_answer_latex=ans,worked_solution_latex=steps,progressive_hints=hints,rubric=[dict(marks=1,criterion=e) for e in steps],facts=[enc(e) for e in f],likely_mistake=mistake,origin='original',examination_source=None,difficulty_status='editorial_design_teacher_pending',demand_rationale=RATIONALES[path][l-1])
